using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Drawing;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class Appearance680Tests {
  static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
  static void Set(WpfScene scene,string field,object value){typeof(WpfScene).GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(scene,value);}
  static double Difference(Matrix3D a,Matrix3D b){return new[]{Math.Abs(a.M11-b.M11),Math.Abs(a.M22-b.M22),Math.Abs(a.M33-b.M33),Math.Abs(a.OffsetX-b.OffsetX),Math.Abs(a.OffsetY-b.OffsetY),Math.Abs(a.OffsetZ-b.OffsetZ)}.Max();}
  static Result Fixture(){var model=new CadAssembly();for(int i=0;i<4;i++){var p=new CadPart("fixed_"+i,"Fixed part "+i,"housing",Color.Gray){Placement=RobotMath.Translation(i*25,0,i*10)};p.Sections.Add(new CadSection(0,5,CadLoop.Round(0,0,5),null));model.Parts.Add(p);}return new Result{P=new Parameters{Kind=0},Model=model};}
  static void Layout(WpfScene scene){scene.Root.Measure(new System.Windows.Size(900,650));scene.Root.Arrange(new System.Windows.Rect(0,0,900,650));}
  public static int Run(string folder){Directory.CreateDirectory(folder);checks=0;bool enabled=SceneAnimation.Enabled;var old=AppSettings.Current;try{
   AppSettings.Current=new AppSettings{AutoSave=false};
   string legacy=Path.Combine(folder,"legacy-settings.json");File.WriteAllText(legacy,"{\"FormatVersion\":2,\"Theme\":1,\"Colors\":{\"Window\":\"#252525\",\"Accent\":\"#123456\"}}",Encoding.UTF8);var migrated=AppSettings.LoadFrom(legacy);Check(migrated.FormatVersion==3&&migrated.ShowHints&&migrated.StartSection==GearStart.Редукторы,"legacy settings retain usable new defaults");Check(!migrated.Colors.ContainsKey("Window")&&migrated.Colors["Accent"]=="#123456","palette migration preserves custom colors");
   foreach(GearAccent accent in Enum.GetValues(typeof(GearAccent))){var settings=new AppSettings{Accent=accent};settings.Validate();Check(UiPalette.Get(settings,"Accent").ToArgb()==UiPalette.AccentSample(accent,true).ToArgb(),"dark accent "+accent);settings.Theme=GearTheme.Светлая;Check(UiPalette.Get(settings,"Accent").ToArgb()==UiPalette.AccentSample(accent,false).ToArgb(),"light accent "+accent);}
   using(var settings=new SettingsForm(null)){settings.Draft.Theme=GearTheme.Системная;settings.Draft.Accent=GearAccent.Зелёный;settings.Draft.ShowHints=false;settings.Draft.StartSection=GearStart.Робототехника;Check(AppSettings.Current.ShowHints&&AppSettings.Current.StartSection==GearStart.Редукторы,"unsaved appearance draft stays isolated");Check(settings.ApplyDraft(),"new settings apply through real settings form");var loaded=AppSettings.LoadFrom(AppSettings.SettingsPath);Check(loaded.Theme==GearTheme.Системная&&loaded.Accent==GearAccent.Зелёный&&!loaded.ShowHints&&loaded.StartSection==GearStart.Робототехника,"all new preferences survive save and reload");}AppSettings.Current=new AppSettings{AutoSave=false};
   using(var scene=new WpfScene()){
    var grouped=Fixture();var bearing=new CadPart("bearing","Bearing","bearing",Color.Gray);bearing.Sections.Add(new CadSection(0,5,CadLoop.Round(0,0,5),new[]{CadLoop.Round(0,0,2)}));grouped.Model.Parts[1].BearingElement=0;grouped.Model.Parts[2].BearingElement=1;grouped.Model.Parts[1].BearingPitch=grouped.Model.Parts[2].BearingPitch=4;grouped.Model.Parts[1].BearingSource=grouped.Model.Parts[2].BearingSource=bearing;Layout(scene);SceneAnimation.Enabled=false;scene.SetResult(grouped,false);var a=scene.Nodes[1].Transform.Matrix;var b=scene.Nodes[2].Transform.Matrix;scene.SetExploded(true);Check(Math.Abs((scene.Nodes[2].Transform.Matrix.OffsetZ-scene.Nodes[1].Transform.Matrix.OffsetZ)-(b.OffsetZ-a.OffsetZ))<1e-8,"bearing components stay together in exploded view");scene.SetExploded(false);scene.SetResult(Fixture(),false);scene.SetExploded(true);Check(!scene.Animating&&scene.Nodes.All(n=>Difference(n.Pose,n.Transform.Matrix)<1e-9),"headless exploded view stays immediate");scene.SetExploded(false);
    SceneAnimation.Enabled=true;var model=Fixture();var placements=model.Model.Parts.Select(p=>p.Placement).ToArray();scene.SetResult(model,false);Check(scene.Animating,"intro is exercised with animations enabled");Check(scene.Nodes.Any(n=>Difference(n.Pose,n.Transform.Matrix)>1e-4),"intro changes display transforms");Check(model.Model.Parts.Select(p=>p.Placement).SequenceEqual(placements),"intro preserves CAD placements");Check(scene.Nodes.All(n=>n.Pose==n.Part.Placement),"intro preserves canonical poses");var frozen=scene.Nodes.Select(n=>n.Frozen).ToArray();
    scene.SetExploded(true);Set(scene,"assembling",false);Set(scene,"explodeProgress",.45);scene.UpdatePose(0,true);var partial=scene.Nodes.Select(n=>n.Transform.Matrix).ToArray();scene.SetExploded(false);Check(scene.Nodes.Select((n,i)=>Difference(n.Transform.Matrix,partial[i])).Max()<1e-8,"rapid explode reversal preserves the displayed pose");Check(scene.Nodes.Select(n=>n.Frozen).SequenceEqual(frozen),"presentation transitions reuse meshes");Check(model.Model.Parts.Select(p=>p.Placement).SequenceEqual(placements),"explosion does not change exported CAD placements");
    scene.SetExploded(true);Set(scene,"explodeProgress",.3);scene.UpdatePose(0,true);scene.ConfigureSection(1,0,true);Check(!scene.Animating,"sectioning finishes presentation motion immediately");Check(scene.Nodes.All(n=>Difference(n.Pose,n.Part.Placement*n.Motion.At(0,n.Index*2.5))<1e-8),"sectioning uses the final exploded geometry");scene.ConfigureSection(-1,0,false);
    scene.SetResult(Fixture(),false);Check(scene.Animating,"fresh model starts intro");Check(scene.BeginPartDrag(scene.Nodes[0].Part.Id,new System.Windows.Point(10,10)),"part dragging is available");Check(!scene.Animating,"dragging finishes presentation before editing placement");scene.EndPartDrag(true);Check(scene.Nodes.All(n=>Difference(n.Pose,n.Transform.Matrix)<1e-8),"drag starts from actual geometry");
    scene.SetExploded(false);scene.SetExploded(true);Set(scene,"explodeProgress",.4);scene.UpdatePose(0,true);scene.Fit();var userTarget=scene.Camera.Target;double userWidth=scene.Camera.Width;Set(scene,"explodeStart",-10.0);typeof(WpfScene).GetMethod("MotionTick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(scene,new object[]{null,EventArgs.Empty});Check(!scene.Animating&&scene.Camera.Target==userTarget&&scene.Camera.Width==userWidth,"user camera choice survives final animation tick");
   }
   File.WriteAllText(Path.Combine(folder,"appearance680-results.txt"),"PASS "+checks+" checks: settings migration, accents and active WPF presentation transitions",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"appearance680-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{SceneAnimation.Enabled=enabled;AppSettings.Current=old;}}
 }
}
